     "dept": "콘텐츠산업과",
     "content": "○ 웹툰페어의 계약성과는 있으나 B2B·B2C 이원화, 타 사업과의 연계 부족으로 「인재양성→IP 제작·유통→취업·창업」의 산업 선순환 구조가 미흡하며,  ’26년 예산 감액 및 인턴십 사업 일몰로 성장동력 약화가 우려됨.\n○ 운영체계 일원화, 행사 인프라 개선, 「인재양성-AI교육-IP 제작지원」 간 연계 강화 및 핵심사업의 안정적 재원 확보 필요함.",
     "status": "추진중",
