     "dept": "콘텐츠산업과",
     "content": "○ 문체국 정원 증원에도 전국체전 인력을 제외하면 기존 부서에서 5명이 감원됨에 따라 인력 공백이 발생하여 문화산업 정책 추진력 약화가 우려됨.\n○ 콘텐츠 산업 특성상 신산업 전환기에 행정 중심 인력 구조로는 신규사업 발굴이 어려우므로, 현장 탐방, 리서치 지원 및 인력 보강을 통해 현장 기반 기획 역량을 강화해야 함.",
