     "dept": "",
     "content": "○ 40억 원 하도급 비리는 내부관리 체계 미비로 인한 구조적 문제로, 권익위 조사 상황 미공유와 조사 직전 인사 조치로 축소·은폐 의혹까지 제기됨.\n○ 재무관리, 감사기능, 인사, 위탁관리 등 전 영역에 대한 정보공유 및 내부관리 체계를 전면 재설계하여 관리감독 기능을 강화할 필요가 있음.",
