     "content": "○ ’24년 제1종 전문박물관으로 등록됐음에도 역사문화원 산하 팀으로 운영되어 위상 확립이 어렵고, 예산·인력 부족으로 유물 확보와 기획전 확대 등 핵심 기능 수행에 한계가 있음.\n○ 개관 초기 정체성 확립을 위해 독립 박물관 체제로 전환하고, 인력 확충과 예산 정상화를 통해 전문박물관에 맞는 운영체계를 구축해야 함.",
