     "dept": "",
     "content": "○ 위원 중복, 임기 오류 등 위원회 관리 부실이 반복되고 위원회 목적과 부합하지 않는 운영 사례와 관련 규정 미준수 문제가 나타나고 있음.\n○ 위원 구성, 임기, 회의 운영, 수당체계 등 위원회 운영 전반을 정비하고 통합 관리체계를 구축해 각 위원회별 기능과 실효성을 강화해야 함.",
