     "content": "○ 뮤지엄숍 근로자의 11개월 계약 관행으로 매년 인력 공백과 휴점이 반복되고, 관람 수요 증가 시 운영 중단·축소로 매출 감소와 민원 증가 등 문제가 발생함.\n○ 서비스 공백 방지를 위해 계약기간을 12개월 이상으로 조정하거나, 대체 인력·정규직 투입 등을 통해 연중 상시 운영을 보장해야 함",
