     "dept": "",
     "content": "○ 3실·3본부·8개 소속기관 등 비대한 조직 구조로 운영 효율성이 낮고, 박물관·미술관도 예산·행정 제약으로 전문적 기획 수행에 한계가 있음.\n○ 재단은 기능 중심으로 조직을 재정비하고, 박물관·미술관은 자율성과 전문성 강화를 위한 별도 운영체계 또는 조직개편을 검토할 필요가 있음.",
