     "dept": "",
     "content": "○ 경기문화재단·경기관광공사 고양 이전이 지연되고 있으며, 이전 이후 조직·기능 재정비 및 직원 지원대책도 마련되지 않은 상황임.\n○ 이전 추진 로드맵을 조속히 확정하고 조직·기능·협업체계를 재정비하며, 직원 생활안정 지원방안을 마련해 이전의 실효성과 정책 신뢰성을 확보할 필요가 있음.",
