     "dept": "",
     "content": "○ 예산의 60% 이상이 위탁·대행사업에 편중되고 고유사업 집행률은 저조하며, 집행이 연말에 집중되는 비효율적 구조가 지속되고 있음.\n○ 예산 증액 논의에 앞서 고유사업을 강화하고, 분기별 집행 관리체계 도입 등 예산 집행 구조를 개선해 운영 효율성을 높여야 함.",
