   "findings": [
    {
     "type": "시정",
     "no": 1,
     "title": "위·수탁 계약의 공정성·공공성 확보",
     "dept": "",
     "content": "○ 공공시설 위·수탁 계약에 상가건물 임대차보호법을 적용하여 동일 업체와 장기 계약을 유지해 왔으나, 공공시설 위·수탁은 공공성·공익성을 고려해야 하므로 상가건물 임대차보호법 적용 시 공정경쟁 저해 및 재단 운영 자율성 약화 문제가 있음.\n○ 재계약 기준 및 절차를 포함한 표준 운영지침과 평가체계를 정비하여 위·수탁 운영의 투명성과 공공성을 강화할 필요가 있음.",
     "status": "추진중",
     "result": "⇒ 경기장 내 시설 임대 및 위·수탁 재계약 기준과 관련하여, 계약의 적법성과 공정성 확보를 위해 변호사 법률 검토 및 자문을 거쳐 재계약 절차 추진하고 있음\n⇒ 향후 본 계약의 특성을 정확히 판단하여, 해당 계약 성질(임대 또는 위수탁)에 맞는 절차 이행 및 관련 규정 재검토"
    },
    {
     "type": "처리",
     "no": 1,
     "title": "직급·보수체계 개편 지연에 따른 조직 안정성 저하",
     "dept": "",
     "content": "○ 직급 및 급여 체계가 개선 없이 정체되어 있고, 8·9급 저임금 구조로 인력 이탈이 지속되면서 조직 안정성과 업무 연속성이 위협받고 있음.\n○ 재정 여건을 고려한 단계적 보수체계 개선안과 승진·처우 개선 방안을 조속히 마련하여 직급·급여 체계를 정상화할 필요가 있음.",
     "status": "추진중",
     "result": "⇒ 2025년 1월 13일부터 5월 26일까지 약 4개월간 월드컵재단 직급·급여 개선\n연구용역을 추진하여 급여 시나리오(안) 및 직급체계(안) 도출 완료\n⇒ 재단 직원 의견수렴 2회 진행 후 경기도·수원시 주무부서 협의를 통한 정원증원 및 직급별 정원 개편(안) 도출 완료 및 2026년 1분기 내 규정 개정 및 적용 추진"
    },
    {
     "type": "처리",
     "no": 2,
     "title": "대규모 행사 안전관리 실전 대응체계 구축",
     "dept": "",
     "content": "○ 대규모 행사 시 안전관리 실태를 점검하고, 사전 준비와 체계적인 훈련을 포함한 실효성 있는 대응체계 마련이 필요함.\n○ 행사 시 안전요원의 전문성 확보와 함께, 행사 주최 측과 재단 간의 사전 안전 점검을 철저히 하고, 안전관리 지침 마련 등 사고 예방 중심의 실질적 위기 대응체계 구축이 필요함.",
     "status": "완료",
     "result": "⇒ 매년 안전기본계획 수립 및 행사 시 재해대처계획서 작성 등 안전관리 지침 마련\n및 행사 관계자와 사전 점검을 철저히 이행하고, 교육을 통해 전 직원의 대응\n능력 향상 노력으로 국제경기 3건, K리그 22건, 대형행사 5건 등을 안전사고\n없이 완료함\n⇒ 2026년 안전기본계획 수립을 완료하였으며, 행사 시 재해대처계획 수립 및 관계자\n사전 회의를 통해 관리를 철저히 하고 코드아담·심폐소생술 훈련등 사고위험\n최소화를 위해 노력하겠음."
    },
    {
     "type": "처리",
     "no": 3,
     "title": "경영평가 최하위 추락 및 5년 연속 적자(재정위기)에 따른 고강도 경영혁신 및 자구책 마련",
     "dept": "",
     "content": "○ 2025년도 경영평가에서 전년 대비 2단계 하락한 최하위 ‘마’등급을 기록하며 도내 22개 기관 중 최하위에 머무르고 있으며, 경영전략이 전년도와 동일하게 답습되고 ESG 경영의 실행력이 결여됨.\n○ 또한 5년 연속 당기순손실(’24년 약 45억 원 적자)을 기록했음에도 신규 수익사업 발굴 실적이 ‘0건’인 상태로 방치됨.\n○ 경영평가 하락의 원인을 정밀 분석하고, 실효성 있는 중장기 경영전략 및 ESG 실행 과제를 원점에서 재수립하고, 단순 대관 수입에 의존하는 구조를 탈피하여, 적자 고리를 끊을 수 있는 실질적인 ‘신규 수익 모델(비즈니스 모델)’을 발굴하는 등 구체적인 재정 건전화 로드맵 마련이 필요함.",
     "status": "추진중",
     "result": "⇒ 재단은 2025년 경영평가에서 전년 대비 2단계 하락한 ‘마’등급을 받은 결과를\n엄중히 받아들이고, 경영평가 대비 개선 대책을 수립함.\n⇒ 기존 전략체계가 전년도와 동일하게 운영된 지적사항을 해소하기 위해 경영체계\n개선 연구용역을 통해 미션·비전·전략을 재정립하고, 환경 변화를 반영한 전략\n과제를 새롭게 도출할 계획임.\n⇒ 용역 결과를 토대로 중장기 지속가능한 경영 체계를 재확립하고 공공성·시스템·\n수익성의 균형 있는 전략 이행을 통해 경영성과와 실행력을 제고해 나가겠음."
    },
    {
     "type": "처리",
     "no": 4,
     "title": "예산 불용·이월 반복에 따른 집행관리 체계 개선",
     "dept": "",
     "content": "○ 예산 증액에도 불용·이월이 반복되며 집행률 부진이 지속되고 있고, 예비비·시설충당금 등 사유는 경영성과 측면에서 설득력이 부족함.\n○ 기획 단계부터 집행·성과관리 전 과정 점검을 강화하고, 연차별 집행계획 관리로 예산의 효율성과 책임성을 제고할 필요가 있음.",
     "status": "완료",
     "result": "⇒ 주요 사업 예산집행 관리 강화 및 세입·세출 운용계획 수립을 통해 2025년에는\n약 88.8%의 예산 집행률을 보이고 있으며, 집행계획 관리를 통해 명시이월금 30\n억 원에서 7억 9천만 원으로 감소 및 재정안정화기금 신설 등 관리체계 구축\n⇒ 연간 자금운용 계획 수립 및 분기별로 예산 운용 현황을 점검하고 기금 및 유휴\n자금에 대한 연도말 점검과 예비비 편성 규모를 단계적으로 현실화 시키는 등\n재정 안정화를 위해 노력하겠음."
    }
   ],
