     "dept": "",
     "content": "○ 직장운동경기부 선수 평균 연봉이 서울/인천/대구/강원/경북에 비해 낮고, 이에 따른 선수 외부 유출의 가능성이 있는 상황임.\n○ 경기도의 위상을 지키기 위한 추가적인 종목 육성, 연봉 인상 등 발전을 위한 지원 강화가 필요함.",
