     "result": "⇒ 경기도청 직장운동경기부는 현재 ‘호봉제’로 운영하고 있고, 타 지자체의 경우 전국 17개 시·도 중 12개 시·도가 연봉제를 운영하고 있어 기본급 수준은 상대적으로 낮을 수 있으나, 우수선수 영입·관리비를 포함한 실질 총 보수 기준으로는 전국 평균 수준을 유지하고 있음.\n⇒ 「경기도청 직장운동경기부 발전방안 연구용역」 결과에 따라 신규 종목 육성, 중장기 발전 전략 수립 등 체계적으로 관리해 나가겠음."
