     "content": "○ 스포츠클럽은 생활체육과 비인기 종목 활성화, 일자리 창출 등 다양한 역할을 수행하고 있으나, 수요에 비해 도비 지원이 부족하고 지역 편중이 커지원 확대가 필요함.\n○ 초등스포츠클럽은 도와 교육청이 지원하는 사업으로, 학교체육 활성화를 위해 도 차원의 안정적인 예산 편성과 교육청과의 협력 체계 마련이 요구됨.",
     "status": "추진중",
     "result": "⇒ 2026년도 지정스포츠클럽 도비사업 참여확대를 위한 계획을 수립중(경기스포츠클럽, 경기유소년스포츠클럽대회)에 있음\n⇒ 또한 유소년스포츠클럽대회는 2025년 예산에서 50% 증액하여 스포츠클럽이 참여할 수 있는 여건을 확충하였음. 다만, 초등스포츠클럽의 경우 도와 시·군예산 미편성으로 전년대비 50% 예산이 삭감되어 운영 예정이며, 교육청과 협력하여 운영 클럽은 50% 미만으로 편성하여 참여인원 축소를 최소화할 예정임."
