     "result": "⇒ 폭력 예방 근절을 위한 가해자 처벌 강화 및 피해 대응 자료등 지속 안내 및 교류(도교육청, 회원종목단체) 하였음\n⇒ 학교폭력을 근절하고 경각심 제고를 위해, 2025년중 지속된 학교폭력 발생과 관련 시군체육회 및 회원종목단체에 폭력 예방을 위한 지속적 폭력 예방 교육 강화 및 즉시 신고 처리 등 지속 안내 완료하였으며, 2025년도 학교운동부 지원사업 대상 선정시 학교폭력, 성폭력 등이 발생된 학교운동부는 선정에서 제외하였음(2026년도 학교운동부 지원사업 추진시에도 필수 반영 예정)\n⇒ 학교폭력가해 학생선수는 징계 처분 사안별 대회(경기) 참가 제한 및 경기인 등록 제한을 병행 처리(’25.10.1.)하고 있음"
