     "dept": "",
     "content": "○ 관리단체로 지정된 종목단체는 체육회가 선수 등록부터 행정까지 전반적인 업무를 대신 수행하면서 업무 부담이 가중되고 있어 인력확가 필요함.\n○ 관리단체의 문제가 해소되더라도 종목단체 운영의 자율성과 공공성 강화를 위해 일정 기간 점검을 거쳐 정회원으로 복귀하는 절차가 필요함.",
