     "result": "⇒ 채용 자격조건에 대한 기준을 변경하여 채용 대상 직위의 직무에 적합한 인재가 채용될 수 있도록 관련 규정 개정(’25.12.)\n⇒ 2026년 예산 편성 시 효율적인 사업 운영을 통한 장애인 체육 활성화 등 정책 효과 증진을 위해 사업 재구조화(14개 단위사업→10개 단위사업) 실시(’25.12.)\n⇒ 2026년 경기도 공공기관 통합 채용으로 결원 채용 예정(’26.3.~)"
