     "title": "장애인 직장운동부 창단 지원사업 일몰 재검토",
     "dept": "",
     "content": "○ 31개 시ㆍ군 중 2024년 기준 29개 시ㆍ군이 여전히 장애인 의무고용률(3.8%)을 달성하지 못하며 부담금을 납부하는 실정이나 이를 해소할 수 있는 장애인 직장운동부 창단 지원사업이 일몰됨을 지적함.\n○ 시ㆍ군 단위의 소규모 직장운동부 운영, 공공기관 연계형 모델 등 사업형태나 지원방식을 개선하는 등 다양한 운영모델을 개발해 장애인 직장운동부 창단 지원사업 재추진 검토를 요구함.",
     "status": "추진중",
     "result": "⇒ 31개 시군장애인체육회 대상 2026년 직장운동부 창단 수요조사 실시(’25.11.)\n⇒ 창단 수요 발생 시 국비 실업팀 지원 창단 공모 사업을 통해 지원 예정이며, 다양한 운영사례 홍보를 통해 수요 증가 시 ’27년 예산 편성을 협의하겠음."
