     "dept": "",
     "content": "○ 사전 고지 없이 경기시간이 변경되어 선수 출전 기회가 박탈되는 등 참가자 권익 보호가 미흡하고, 장비 오류·재경기 반복 등 기본 운영요건 미충족 사례가 확인됨.\n○ 경기운영 및 현장대응 표준 매뉴얼을 개선하고 운영 책임성·중립성을 확보할 수 있도록 시스템 전반의 개선이 필요함.",
