   "findings": [
    {
     "type": "처리",
     "no": 1,
     "title": "DMZ다큐영화제 홍보전략 전면 재정비 필요",
     "dept": "",
     "content": "○ 경기도 대표 영화제임에도 불구하고 언론 노출과 대외 홍보가 부족하고, 다양한 채널을 활용한 적극적인 홍보 전략 마련이 필요함.\n○ 홍보 예산이 매우 적어 효과적인 홍보에 한계가 있으며, 콘텐츠 제작 예산의 집행률도 낮은 만큼, 예산을 유연하게 재편성하여 홍보비를 확대하고 영화제의 위상과 인지도를 높일 수 있는 전략 마련이 필요함.",
     "status": "추진중",
     "result": "⇒ DMZ국제다큐멘터리영화제 홍보 실태 및 참여자 분석을 토대로 경기도 및 수도권 주요 교통거점 광고물 설치 추진\n⇒ 영화제 주 참여자(20~40대 여성) 대상 SNS 인플루언서 콘텐츠(유튜브) 제작\n⇒ 지역 주민 및 도내 청년층 참여 확대를 위한 지역 광고·이벤트 확대\n⇒ 대중에게 어필할 수 있는 디자인 굿즈 제작과 공간 조성(미술감독제 활용)을 통해 영화제 인지도 제고 및 관객 확보 전략을 마련하겠음"
    },
    {
     "type": "처리",
     "no": 2,
     "title": "영화제 도내기업 참여 확대를 위한 관리체계 정비 필요",
     "dept": "",
     "content": "○ 계약관련 자료관리 및 검증체계 강화와 도내 기업 참여 확대, 도내 기업 우대지침 실효성 강화 등 계약관리체계 전반의 재정비가 필요함.",
     "status": "추진중",
     "result": "⇒ 영화제 도내 기업 참여 확대를 위해 업무 연찬회를(25.12월) 개최하여 내부교육 실시 및 의견 수렴하였음\n⇒ 이를 토대로 향후 도내 기업 참여 확대 및 발굴을 위한 내부 지침 제정하겠음(26. 상반기)"
    },
    {
     "type": "처리",
     "no": 3,
     "title": "계약직 인력 이탈 문제 해결 및 조직 안정화 대책 마련",
     "dept": "",
     "content": "○ 상시 인력의 지속적인 이탈, 기초 행정자료의 오류, 관리체계 부재는 업무 연속성과 조직 안정성을 저해하고 있으나, 이탈 원인 진단 없이 인력 교체만 되고 있음.\n○ 이탈 요인(업무분장·보수체계·조직문화 등) 진단과 함께 처우 개선, 인센티브 강화 등 인력 유지 대책 마련 및 장기 근속을 위한 조직 안정성 확보가 필요함.",
     "status": "추진중",
     "result": "⇒ 영화제 조직은 영화제 개최 전반 및 연중 사업을 수행하는 정규직 인력과 영화제 개최기간에 한정하여 필요한 단기 계약직 인력으로 구성되어 있음\n⇒ 일반직(정규직) 인력은 법인 정원 인력의 이탈 없이 안정적으로 업무를 수행하고 있으나, 전문인력(단기직)의 경우, 영화제 특성상 행사 종료 이후 지속적인 업무가 없어 장기 계약을 보장하기 어려우며, 이에 따라 이직이 구조적으로 발생할 수밖에 없는 상황임\n⇒ 그럼에도 영화제는 전문인력(단기직) 이탈 최소화를 위해 직원 간담 등을 통해 근무여건 안내 및 의견 청취를 강화하고 지속적인 의견 수렴을 통해 처우 개선에 노력하겠음"
    },
    {
     "type": "건의",
     "no": 1,
     "title": "영화제 관객 기반 확충 및 마니아층 확보 위한 장기 전략 수립",
     "dept": "",
     "content": "○ 국가 대표 영화제로의 성장 잠재력이 있으나, 관객 기반 협소, 마니아층 부족 및 행사 중심 운영으로 지속적 발전이 어려운 실정임.\n○ 안정적 성장을 위해 전문 상영관 협력, 청년·지역 커뮤니티 연계, 참여형 교육 프로그램 운영 등 관객 유입과 참여 확대를 위한 구조 마련이 필요함.",
     "status": "추진중",
     "result": "⇒ 청년·대학생·지역 시민단체와 연계한 참여형 프로그램을 관객 개발 전략과 연결(기획·공동체 상영회, 아카데미 배지, 월간 다큐 살롱 등)\n⇒ 관람–토론–교육–창작이 연결되는 단계형 참여 프로그램 운영으로 다큐멘터리 이해도와 몰입도 제고\n⇒ 다큐멘터리를 관람 중심에서 참여 중심 문화로 전환해 마니아 관객층을 확보하고 지속적 발전을 도모하겠음"
    }
   ],
