     "no": 1,
     "title": "남한산성 세계유산 재해관리체계 정비",
     "dept": "",
     "content": "○ 자연재해로 훼손된 수목의 38%만 정비되어 복구가 지연되고, 상시·선제 대응체계와 인력·예산이 부족해 세계유산 관리·복구 역량이 약화되고 있음.\n○ 전문 인력 확충과 처우 개선을 통해 관리역량을 강화하고, 재해 대응·복구 예산을 확대하여 지속 가능한 관리체계를 구축해야 함.",
